def limit_error_rate(fails, timeout, exception=ErrorRateExceeded):
    """If function fails to complete fails times in a row,
       calls to it will be intercepted for timeout with exception raised instead."""
    if isinstance(timeout, timedelta):
        timeout = timeout.total_seconds()

    def decorator(func):
        func.fails = 0
        func.blocked = None

        @wraps(func)
        def wrapper(*args, **kwargs):
            if func.blocked:
                if datetime.now() - func.blocked < timedelta(seconds=timeout):
                    raise exception
                else:
                    func.blocked = None

            try:
                result = func(*args, **kwargs)
            except:  # noqa
                func.fails += 1
                if func.fails >= fails:
                    func.blocked = datetime.now()
                raise
            else:
                func.fails = 0
                return result
        return wrapper
    return decorator


def throttle(times, period):
    """Decorator that limits function calls to at most ``times`` within ``period`` seconds.

    Supports both int (seconds) and timedelta as period argument.
    """
    if isinstance(period, timedelta):
        period = period.total_seconds()

    def decorator(func):
        import collections
        timestamps = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            # Remove old timestamps outside the window
            while timestamps and timestamps[0] <= now - period:
                timestamps.pop(0)

            if len(timestamps) >= times:
                # Rate exceeded, wait until oldest timestamp is out of window
                wait_time = timestamps[0] + period - now
                if wait_time > 0:
                    time.sleep(wait_time)
                # Clean up again after waiting
                now = time.time()
                while timestamps and timestamps[0] <= now - period:
                    timestamps.pop(0)

            timestamps.append(time.time())
            return func(*args, **kwargs)

        # Expose helper names
        wrapper._timestamps = timestamps
        return wrapper

    return decorator


